const httpResponse = $node["HTTP Request Article"].json;
let html = httpResponse.data || httpResponse.body || httpResponse;

let originalUrl = $node["Recup flux RSS"].json.url || '';

console.log('✅ URL récupérée:', originalUrl);

if (typeof html === 'object') {
  html = html.data || html.body || Object.values(html).find(v => typeof v === 'string' && v.length > 100) || '';
}

console.log('Type de HTML:', typeof html);
console.log('Longueur HTML:', html.length);

function stripHtml(htmlContent) {
  if (!htmlContent || typeof htmlContent !== 'string') return '';
  let text = htmlContent.replace(/<script[^>]*>.*?<\/script>/gis, '');
  text = text.replace(/<style[^>]*>.*?<\/style>/gis, '');
  text = text.replace(/<[^>]+>/g, ' ');
  text = text.replace(/\s+/g, ' ');
  text = text.replace(/&nbsp;/g, ' ');
  text = text.replace(/&amp;/g, '&');
  text = text.replace(/&lt;/g, '<');
  text = text.replace(/&gt;/g, '>');
  text = text.replace(/&quot;/g, '"');
  text = text.replace(/&#39;/g, "'");
  return text.trim();
}

const cleanText = stripHtml(html);
const truncatedText = cleanText.substring(0, 10000);

console.log('Texte nettoyé, longueur:', truncatedText.length);
console.log('Premiers 100 caractères:', truncatedText.substring(0, 100));

return {
  json: {
    url: originalUrl,
    content: truncatedText,
    contentLength: truncatedText.length,
    hasContent: truncatedText.length > 100
  }
};

const claudeResponse = $input.first().json;
const tokensUsed = (claudeResponse.usage?.input_tokens || 0) + (claudeResponse.usage?.output_tokens || 0);

let rawText = claudeResponse.content?.[0]?.text || '';

// Nettoyage au cas où Claude ajoute des backticks malgré la consigne
const clean = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let parsed = {};
try {
  parsed = JSON.parse(clean);
} catch (e) {
  console.log('❌ JSON parse error:', e.message);
  console.log('Raw:', rawText.substring(0, 200));
  // Retourne un objet vide → sera filtré par If(article vide)
  return { json: { titre: '', importance: 0 } };
}

const tickers = Array.isArray(parsed.tickers)
  ? parsed.tickers.join(',')
  : (parsed.tickers || '');

console.log('✅ Parsed:', parsed.titre, '| Secteur:', parsed.secteur, '| Importance:', parsed.importance);

return {
  json: {
    url: $node["Cleaner HTML"].json.url || 'URL non disponible',
    date: new Date().toISOString(),
    titre: parsed.titre || '',
    titre_en: parsed.titre_en || '',
    secteur: parsed.secteur || 'Non défini',
    importance: parseInt(parsed.importance) || 0,
    sentiment: parsed.sentiment || 'Neutre',
    tickers,
