    original_title: $node["Recup flux RSS"].json.title || '',
    // Champs structurés pour le futur
    resume: parsed.resume || '',
    points_cles: parsed.points_cles || [],
    impact_marches: parsed.impact_marches || '',
    opportunites: parsed.opportunites || '',
  }
};

// Gestion des erreurs — si le flux RSS a échoué, on skip
const input = $input.first().json;
if (input.error || input.statusCode === 404 || input.statusCode >= 400) {
  console.log('⚠️ Flux RSS en erreur, skip:', input.url || 'URL inconnue');
  return [];
}

// Récupérer le flux RSS brut
const response = input;
let rssText = response.body || response.data || response['data '] || '';

if (typeof rssText === 'object') {
  rssText = JSON.stringify(rssText);
}

if (!rssText || rssText.length < 50) {
  console.log('⚠️ Flux RSS vide ou trop court, skip');
  return [];
}

function extract(text, tag) {
  const regex = new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'gi');
  const matches = [];
  let match;
  while ((match = regex.exec(text)) !== null) {
    matches.push(match[1]);
  }
  return matches;
}

function cleanText(text) {
  return text
    .replace(/<!\\[CDATA\\[(.*?)\\]\\]>/gs, '$1')
    .replace(/<[^>]+>/g, '')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&#39;/g, "'")
    .trim();
}

const items = extract(rssText, 'item');

console.log(`${items.length} articles trouvés dans le flux RSS`);

if (items.length === 0) {
  console.log('Aucun article trouvé, skip');
  return [];
}

const articles = items.map(itemText => {
  const titles = extract(itemText, 'title');
  const links = extract(itemText, 'link');
  const pubDates = extract(itemText, 'pubDate');
  const descriptions = extract(itemText, 'description');

  return {
    title: cleanText(titles[0] || ''),
    url: cleanText(links[0] || ''),
    pubDate: cleanText(pubDates[0] || ''),
    description: cleanText(descriptions[0] || '')
  };
});

// Filtrer les articles récents (dernières 12h)
const now = new Date();
const twelveHoursAgo = new Date(now.getTime() - 12 * 60 * 60 * 1000);

const recentArticles = articles.filter(article => {
  if (!article.pubDate) return true;
  try {
    const pubDate = new Date(article.pubDate);
    return pubDate >= twelveHoursAgo;
  } catch (e) {
    return true;
  }
});

console.log(`${recentArticles.length} articles récents`);

if (recentArticles.length === 0 && articles.length > 0) {
  console.log('Aucun article récent, on prend les 3 premiers');
  return articles.slice(0, 3).map(a => ({ 
    json: { url: a.url, title: a.title, description: a.description }
  }));
}
// Si 0 articles trouvés → flag pour alerte
if (items.length === 0) {
  return [{ 
    json: { 
      _fluxMort: true, 
      url: input.url || 'URL inconnue',
      source: input.source || 'Source inconnue'
    } 
