}
// Entités VIP — jamais éjectées par le cap à 3
// Charger toutes les entités VIP (un item par entité)
const VIP_ENTITIES = $items("Charger entités VIP")
  .map(i => i.json.name.toLowerCase());

function isVIP(article) {
  const text = (article.title + ' ' + article.description).toLowerCase();
  return VIP_ENTITIES.some(e => text.includes(e));
}

const vipArticles = recentArticles.filter(isVIP);
const nonVipArticles = recentArticles.filter(a => !isVIP(a));

// Diversité par entité : max 3 articles par entité VIP
const entityCount = {};
const diverseVipArticles = [];

for (const article of vipArticles) {
  const text = (article.title + ' ' + article.description).toLowerCase();
  const primaryEntity = VIP_ENTITIES.find(e => text.includes(e)) || 'other';
  entityCount[primaryEntity] = (entityCount[primaryEntity] || 0) + 1;
  if (entityCount[primaryEntity] <= 3) {
    diverseVipArticles.push(article);
  }
}

// Identifier la source courante
const currentSource = ($node["fetch source RSS"]?.json?.source || 
                       $input.first().json?.source || '').toLowerCase();
const isTechCrunch = currentSource.includes('techcrunch');

// Cap TechCrunch à 1 article par run
const maxArticles = isTechCrunch ? 1 : 3;

const capped = [...diverseVipArticles, ...nonVipArticles.slice(0, maxArticles)];

return capped.map(article => ({
