// 1. Normalisation
function normalize(t) {
  if (!t) return '';
  return t.toLowerCase()
    .replace(/[^a-z0-9\s]/g, '')
    .split(/\s+/)
    .filter(w => w.length > 3)
    .sort()
    .join(' ');
}

// 2. Score Jaccard
function jaccard(a, b) {
  if (!a || !b) return 0;
  const setA = new Set(a.split(' '));
  const setB = new Set(b.split(' '));
  const inter = [...setA].filter(x => setB.has(x));
  const union = new Set([...setA, ...setB]);
  return union.size === 0 ? 0 : inter.size / union.size;
}

// 3. Extraire résumé exécutif (pour zone grise Claude)
function extractResume(analysis) {
  if (!analysis) return '';
  const match = analysis.match(/RÉSUMÉ EXÉCUTIF[\s\S]*?\n([\s\S]*?)(?=\n#|\n\n\n|$)/i);
  return match ? match[1].trim().substring(0, 400) : analysis.substring(0, 400);
}

