const haikuResponse = $input.first().json;
const isConfirmed = haikuResponse.content?.[0]?.text?.trim().includes('CONFIRME');
const article = $node["If (importance 5)"].json;
return { json: { ...article, haikuConfirmed: isConfirmed } };

const watchlistTickers = $items("Charger Watchlist")
  .map(i => i.json.ticker.toUpperCase());

const articleTickers = ($json.tickers || '')
  .split(',')
  .map(t => t.trim().toUpperCase())
  .filter(t => t.length > 0);

const matchedTicker = articleTickers.find(t => watchlistTickers.includes(t));

return { json: { 
  ...$json, 
  watchlistMatch: !!matchedTicker,
  watchlistTicker: matchedTicker || ''
}};
